mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.LICENSE_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.PRODUCT_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.VENDOR_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.VENDOR_NAME = #{vendorName}
AND T1.LICENSE_MODEL_CD = #{licenseModelCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.LICENSE_ID AS LICENSE_ID, T1.PRODUCT_NAME AS PRODUCT_NAME, T1.VENDOR_NAME AS VENDOR_NAME,
           T1.LICENSE_MODEL_CD AS LICENSE_MODEL_CD, T1.QTY AS QTY, T1.ANNUAL_MAINT_AMT AS ANNUAL_MAINT_AMT,
           T1.CURRENCY_CD AS CURRENCY_CD, T1.CONTRACT_END_DT AS CONTRACT_END_DT,
           T1.MOBILITY_YN AS MOBILITY_YN, T1.REMARK AS REMARK,
           (SELECT NVL(SUM(A.ALLOCATED_QTY),0) FROM TB_IF_ASSET_LICENSE_PILOT A WHERE A.LICENSE_ID = T1.LICENSE_ID) AS ALLOCATED_QTY
      FROM TB_IF_LICENSE_PILOT T1

     ORDER BY T1.CONTRACT_END_DT, T1.LICENSE_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_LICENSE_PILOT (
  LICENSE_ID, PRODUCT_NAME, VENDOR_NAME, LICENSE_MODEL_CD, QTY, ANNUAL_MAINT_AMT,
  CURRENCY_CD, CONTRACT_END_DT, MOBILITY_YN, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{licenseId}, #{productName}, #{vendorName}, #{licenseModelCd}, #{qty}, #{annualMaintAmt},
  #{currencyCd}, #{contractEndDt}, #{mobilityYn}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.update:
UPDATE TB_IF_LICENSE_PILOT
   SET PRODUCT_NAME=#{productName}, VENDOR_NAME=#{vendorName}, LICENSE_MODEL_CD=#{licenseModelCd},
       QTY=#{qty}, ANNUAL_MAINT_AMT=#{annualMaintAmt}, CURRENCY_CD=#{currencyCd},
       CONTRACT_END_DT=#{contractEndDt}, MOBILITY_YN=#{mobilityYn}, REMARK=#{remark},
       CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE LICENSE_ID=#{licenseId}

mapper.delete:
DELETE FROM TB_IF_LICENSE_PILOT
 WHERE LICENSE_ID IN
#{id}
